task.vi:
Tìm lỗi trong mỗi trường hợp sau và giải thích cách sửa:
a) Câu lệnh sau dự định in ký tự 'c':
    printf("%s\n", 'c');
b) Câu lệnh sau dự định in 9.375%:
    printf("%.3f%", 9.375);
c) Câu lệnh sau dự định in ký tự đầu tiên của chuỗi "Monday":
    printf("%c\n", "Monday");
d) puts(""A string in quotes"");
e) printf(%d%d, 12, 20);
f) printf("%c", "x");
g) printf("%s\n", 'Richard');

task.en:
Find the error in each of the following and explain how it can be corrected:
a) The following statement should print the character 'c':
    printf("%s\n", 'c');
b) The following statement should print 9.375%:
    printf("%.3f%", 9.375);
c) The following statement should print the first character of the string "Monday":
    printf("%c\n", "Monday");
d) puts(""A string in quotes"");
e) printf(%d%d, 12, 20);
f) printf("%c", "x");
g) printf("%s\n", 'Richard');

example.code:
#include <iostream>
#include <cstdio>

int main() {
    int month1 = 0, day1 = 0, year1 = 0;
    int month2 = 0, day2 = 0, year2 = 0;

    // Reading date using scanf assignment suppression character (*c)
    // Simulates reading mm-dd-yyyy and mm/dd/yyyy
    if (std::scanf("%d%*c%d%*c%d", &month1, &day1, &year1) == 3) {
        std::printf("C-style parsed: month = %d  day = %d  year = %d\n", month1, day1, year1);
    }

    // Idiomatic, type-safe C++17 reading
    char sep1 = 0, sep2 = 0;
    if (std::cin >> month2 >> sep1 >> day2 >> sep2 >> year2) {
        std::cout << "C++17 parsed:   month = " << month2
                  << "  day = " << day2
                  << "  year = " << year2 << "\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdio>

int main() {
    int intVal = 1234;
    double floatVal = 123.456789;
    int octVal = 100;
    int width = 8, prec = 3;

    // 1. Right justified in 10-digit field
    std::printf("Exercise 9.3a: [%10d]\n", intVal);

    // 2. Exponential notation with sign and 3 digits of precision
    std::printf("Exercise 9.3b: [%+.3e]\n", floatVal);

    // 3. Octal with leading 0
    std::printf("Exercise 9.3d: [%#o]\n", octVal);

    // 4. Dynamic width and precision with *
    std::printf("Exercise 9.3g: [%*.*f]\n", width, prec, 87.4573);

    // 5. Modern C++17 equivalent stream output
    std::cout << "C++17 dynamic: [" 
              << std::setw(width) << std::fixed << std::setprecision(prec) << 87.4573 
              << "]\n";

    return 0;
}
